-- 69_new_zone_graveyards.sql — map 751 Lordaeron extension, DB step 8.
-- GENERATED by Custom/Documentation/scripts/gen_map751_graveyards.py — do not hand-edit.
--
-- Map 751 had ZERO rows in game_graveyard, so every death anywhere in the eight
-- zones fell back to whatever the core could find — the single stale 4924 link.
-- This ports Blizzard's own Cataclysm graveyard set: positions from the 4.3.x
-- WorldSafeLocs.dbc (cata_world has no worldsafelocs table, so they are literals),
-- zone links and faction routing from cata_world.graveyard_zone.
--
-- 40 graveyards at ids 15100-15139 (band verified free,
-- live max was 15063 from the map-750 set), 42 zone links.
-- Faction 469 = Alliance only, 67 = Horde only, 0 = both.
-- Undercity ghosts route to the Tirisfal set: 4934 has no terrain of its own.
-- A stock Spirit Healer (6491) is spawned at every graveyard, guids allocated
-- from MAX(guid)+1 at apply time — spawn guids are 24-bit, see 67_.

-- ---------------------------------------------------------------------------
-- Graveyard locations
-- ---------------------------------------------------------------------------
DELETE FROM `graveyard_zone` WHERE `ID` BETWEEN 15100 AND 15299;
DELETE FROM `game_graveyard` WHERE `ID` BETWEEN 15100 AND 15299;
DELETE FROM `graveyard_zone` WHERE `GhostZone` IN (4924,4932,4933,4935,4936,4937,4938,4939);


-- ---------------------------------------------------------------------------
-- Zone links (which graveyard a ghost in which zone routes to, per faction)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Spirit healers, one per graveyard
-- ---------------------------------------------------------------------------
DELETE c FROM `creature` c WHERE c.`map` = 751 AND c.`id` = 6491;
SET @sh := (SELECT MAX(`guid`) FROM `creature`);
   `position_x`,`position_y`,`position_z`,`orientation`,`spawntimesecs`,
   `wander_distance`,`currentwaypoint`,`curhealth`,`curmana`,`MovementType`,
   `npcflag`,`unit_flags`,`ScriptName`,`VerifiedBuild`,`Comment`)
SELECT
  @sh := @sh + 1, 6491, 751, z.`zone`, z.`zone`,
  1, 1, 0, g.`x`, g.`y`, g.`z`, 0, 300, 0, 0, 1, 0, 0, 0, 0, '', 0, 'Lordaeron-ext GY'
FROM `game_graveyard` g
-- JOIN, not a scalar subquery: guarantees a non-null zone (the column is NOT NULL)
-- and quietly skips any graveyard that ended up with no zone link.
-- One row per graveyard even when it serves several zones.
JOIN (SELECT `ID`, MIN(`GhostZone`) AS `zone` FROM `graveyard_zone` GROUP BY `ID`) z
  ON z.`ID` = g.`ID`
WHERE g.`Map` = 751 AND g.`ID` BETWEEN 15100 AND 15299;

-- guid ceiling guard (0xFFFFFF); must return 0
SELECT 'PROBLEM: spirit healer guid over cap' AS problem, COUNT(*) AS n
FROM `creature` WHERE `guid` > 16777215;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
SELECT 'graveyards on map 751' AS what, COUNT(*) AS n FROM `game_graveyard` WHERE `Map` = 751
UNION ALL SELECT 'zone links', COUNT(*) FROM `graveyard_zone`
  WHERE `GhostZone` IN (4924,4932,4933,4935,4936,4937,4938,4939)
UNION ALL SELECT 'spirit healers spawned', COUNT(*) FROM `creature`
  WHERE `map` = 751 AND `id` = 6491;

SELECT `GhostZone`, COUNT(*) AS graveyards, SUM(`Faction`=0) AS both_factions,
       SUM(`Faction`=469) AS alliance, SUM(`Faction`=67) AS horde
FROM `graveyard_zone`
WHERE `GhostZone` IN (4924,4932,4933,4935,4936,4937,4938,4939)
GROUP BY `GhostZone` ORDER BY `GhostZone`;

-- every zone with spawns must have at least one graveyard reachable by BOTH
-- factions, or one faction dies into a permanent corpse run
SELECT 'PROBLEM: zone with no neutral/either-faction graveyard' AS problem, z.`zone`
FROM (SELECT DISTINCT `zoneId` AS `zone` FROM `creature` WHERE `map` = 751) z
WHERE NOT EXISTS (SELECT 1 FROM `graveyard_zone` g
                  WHERE g.`GhostZone` = z.`zone` AND g.`Faction` = 0)
  AND NOT (EXISTS (SELECT 1 FROM `graveyard_zone` g2 WHERE g2.`GhostZone` = z.`zone` AND g2.`Faction` = 469)
       AND EXISTS (SELECT 1 FROM `graveyard_zone` g3 WHERE g3.`GhostZone` = z.`zone` AND g3.`Faction` = 67));
